import{_ as r,o as d,c as e,a2 as o}from"./chunks/framework.BauHmMU1.js";const l=JSON.parse('{"title":"第 8 章 实际应用场景分析","description":"","frontmatter":{},"headers":[],"relativePath":"08-scenarios.md","filePath":"08-scenarios.md","lastUpdated":1792595797000}'),a={name:"08-scenarios.md"};function s(n,t,c,_,i,g){return d(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="第-8-章-实际应用场景分析" tabindex="-1">第 8 章 实际应用场景分析 <a class="header-anchor" href="#第-8-章-实际应用场景分析" aria-label="Permalink to &quot;第 8 章 实际应用场景分析&quot;">​</a></h1><table tabindex="0"><thead><tr><th>场景</th><th>为什么选 WebSocket</th><th>技术要点</th></tr></thead><tbody><tr><td><strong>即时通讯/聊天室</strong></td><td>双向高频、低延迟</td><td>消息幂等去重、历史消息与实时消息对账、在线状态（presence）</td></tr><tr><td><strong>实时数据看板</strong></td><td>服务端高频推送指标</td><td>前端 rAF 批量渲染、订阅调速（1Hz/10Hz 分级）、窗口化列表</td></tr><tr><td><strong>协同编辑（文档/白板）</strong></td><td>多人操作需即时同步</td><td>OT/CRDT 冲突解决算法、操作序号、断线操作回放</td></tr><tr><td><strong>金融行情推送</strong></td><td>毫秒级延迟敏感、数据量大</td><td>二进制协议（Protobuf）、增量更新、本地缓存快照 + 增量合并</td></tr><tr><td><strong>在线游戏</strong></td><td>状态同步频率极高（10~60Hz）</td><td>帧同步/状态同步选型、UDP 类需求可考虑 WebTransport/WebRTC DataChannel</td></tr><tr><td><strong>通知/工单/审批提醒</strong></td><td>服务端单向推送为主</td><td>低频场景也可考虑 SSE（更简单，自带重连）</td></tr><tr><td><strong>物联网设备监控</strong></td><td>海量设备长连接</td><td>单机连接数优化（百万级需 C10M 方案）、MQTT 协议对比评估</td></tr></tbody></table><p><strong>不适合 WebSocket 的场景</strong>：一次性数据查询、低频 CRUD、可被 CDN 缓存的内容——这些用普通 HTTP 更简单、可缓存、易扩展。</p><hr>',4)])])}const p=r(a,[["render",s]]);export{l as __pageData,p as default};
